import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.PriorityQueue;

/**
 * Computes a Minimum Spanning Tree (MST) of an undirected, weighted graph using
 * Prim's algorithm.
 *
 * <p>The algorithm operates on an adjacency-list {@link Graph}, so edge enumeration is
 * proportional to the number of edges rather than to {@code V^2}. Combined with a binary
 * heap to select the next cheapest crossing edge, the running time is {@code O(E log V)},
 * which is efficient for sparse graphs. A convenience adapter,
 * {@link Graph#fromAdjacencyMatrix(int[][])}, accepts the classic matrix form.
 */
final class PrimsMst {

    private PrimsMst() {
        // Utility class: no instances.
    }

    /**
     * An edge of the minimum spanning tree, connecting {@code from} to {@code to}
     * with the given {@code weight}.
     */
    record Edge(int from, int to, int weight) {}

    /**
     * The result of an MST computation: the chosen edges and their total weight.
     */
    record MstResult(List<Edge> edges, long totalWeight) {
        MstResult {
            edges = List.copyOf(edges);
        }
    }

    /**
     * An undirected, weighted graph stored as adjacency lists. Edges are added in both
     * directions; weights must be positive.
     */
    static final class Graph {

        /** Sentinel weight indicating "no edge" in an adjacency matrix. */
        private static final int NO_EDGE = 0;

        /** A weighted link to a neighbouring vertex. */
        private record Neighbor(int vertex, int weight) {}

        private final List<List<Neighbor>> adjacency;

        Graph(int vertexCount) {
            if (vertexCount < 0) {
                throw new IllegalArgumentException("Vertex count must not be negative: " + vertexCount);
            }
            adjacency = new ArrayList<>(vertexCount);
            for (int i = 0; i < vertexCount; i++) {
                adjacency.add(new ArrayList<>());
            }
        }

        int vertexCount() {
            return adjacency.size();
        }

        /** Adds an undirected edge between {@code u} and {@code v} with positive {@code weight}. */
        void addEdge(int u, int v, int weight) {
            checkVertex(u);
            checkVertex(v);
            if (weight <= 0) {
                throw new IllegalArgumentException("Edge weight must be positive: " + weight);
            }
            adjacency.get(u).add(new Neighbor(v, weight));
            adjacency.get(v).add(new Neighbor(u, weight));
        }

        private List<Neighbor> neighbors(int vertex) {
            return adjacency.get(vertex);
        }

        private void checkVertex(int vertex) {
            if (vertex < 0 || vertex >= adjacency.size()) {
                throw new IndexOutOfBoundsException("Vertex out of range: " + vertex);
            }
        }

        /**
         * Builds a {@code Graph} from a square, symmetric adjacency matrix where
         * {@code matrix[u][v] == 0} denotes the absence of an edge. Only the upper
         * triangle is read, so the edge is added exactly once.
         */
        static Graph fromAdjacencyMatrix(int[][] matrix) {
            if (matrix == null) {
                throw new IllegalArgumentException("Adjacency matrix must not be null.");
            }
            for (int[] row : matrix) {
                if (row == null || row.length != matrix.length) {
                    throw new IllegalArgumentException("Adjacency matrix must be square.");
                }
            }
            Graph graph = new Graph(matrix.length);
            for (int u = 0; u < matrix.length; u++) {
                for (int v = u + 1; v < matrix.length; v++) {
                    if (matrix[u][v] != NO_EDGE) {
                        graph.addEdge(u, v, matrix[u][v]);
                    }
                }
            }
            return graph;
        }
    }

    /**
     * Computes the minimum spanning tree of {@code graph}.
     *
     * @param graph an undirected, weighted graph
     * @return the MST edges (in the order vertices are added) and their total weight
     * @throws IllegalArgumentException if {@code graph} is null or not connected
     */
    static MstResult compute(Graph graph) {
        if (graph == null) {
            throw new IllegalArgumentException("Graph must not be null.");
        }
        int vertexCount = graph.vertexCount();
        if (vertexCount == 0) {
            return new MstResult(List.of(), 0L);
        }

        boolean[] inTree = new boolean[vertexCount];
        List<Edge> mstEdges = new ArrayList<>(vertexCount - 1);
        long totalWeight = 0L;

        // Min-heap of candidate crossing edges, ordered by weight.
        PriorityQueue<Edge> frontier = new PriorityQueue<>(Comparator.comparingInt(Edge::weight));
        expandFrom(graph, inTree, 0, frontier);

        while (!frontier.isEmpty() && mstEdges.size() < vertexCount - 1) {
            Edge cheapest = frontier.poll();
            if (inTree[cheapest.to()]) {
                continue; // Stale entry: the endpoint was already connected.
            }
            mstEdges.add(cheapest);
            totalWeight += cheapest.weight();
            expandFrom(graph, inTree, cheapest.to(), frontier);
        }

        if (mstEdges.size() != vertexCount - 1) {
            throw new IllegalArgumentException("Graph is not connected; no spanning tree exists.");
        }
        return new MstResult(mstEdges, totalWeight);
    }

    /**
     * Marks {@code vertex} as part of the tree and pushes every edge leading from it to
     * a vertex not yet in the tree onto the frontier.
     */
    private static void expandFrom(Graph graph, boolean[] inTree, int vertex, PriorityQueue<Edge> frontier) {
        inTree[vertex] = true;
        for (Graph.Neighbor neighbor : graph.neighbors(vertex)) {
            if (!inTree[neighbor.vertex()]) {
                frontier.add(new Edge(vertex, neighbor.vertex(), neighbor.weight()));
            }
        }
    }

    /** Renders an MST result as a human-readable edge/weight table. */
    static String format(MstResult result) {
        StringBuilder sb = new StringBuilder("Edge \tWeight");
        for (Edge edge : result.edges()) {
            sb.append('\n').append(edge.from()).append(" - ").append(edge.to())
              .append('\t').append(edge.weight());
        }
        sb.append("\nTotal weight: ").append(result.totalWeight());
        return sb.toString();
    }

    public static void main(String[] args) {
        int[][] graph = {
            { 0, 2, 0, 6, 0 },
            { 2, 0, 3, 8, 5 },
            { 0, 3, 0, 0, 7 },
            { 6, 8, 0, 0, 9 },
            { 0, 5, 7, 9, 0 },
        };

        System.out.println(format(compute(Graph.fromAdjacencyMatrix(graph))));
    }
}
